mapper.sql:
FROM sys_user_role r JOIN sys_user u ON u.id=r.user_id
WHERE r.role_id=#{query.roleId}
AND (u.username LIKE CONCAT('%',#{query.keyword},'%') OR u.display_name LIKE CONCAT('%',#{query.keyword},'%'))
AND r.organization_id=#{query.grantOrganizationId}
AND (r.organization_id IN #{id}
 OR (r.organization_id IS NULL AND EXISTS (SELECT 1 FROM sys_user_organization m WHERE m.user_id=r.user_id AND m.organization_id IN #{id})))AND 1=0

FROM sys_user u JOIN sys_user_organization uo ON uo.user_id = u.id
WHERE uo.organization_id = #{organizationId}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.display_name LIKE CONCAT('%', #{keyword}, '%'))

