FOR UPDATE

where.if:
AND EXISTS (SELECT 1 FROM sys_user_role identity_grant JOIN sys_role identity_role ON identity_role.id=identity_grant.role_id
    WHERE identity_grant.user_id=sys_user.id AND identity_role.status='ENABLED' AND identity_role.role_code=#{query.identityRoleCode}


            AND (identity_grant.organization_id IS NULL OR identity_grant.organization_id IN #{id})
        AND 1=0
    )

mapper.update:
UPDATE sys_user
SET username = CASE WHEN username = #{expectedMobile} THEN #{newMobile} ELSE username END,
    mobile = #{newMobile},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND mobile = #{expectedMobile}
